def _plot_dendrogram(icoords, dcoords, ivl, p, n, mh, orientation, no_labels, color_list, leaf_font_size=None, leaf_rotation=None, contraction_marks=None, ax=None, above_threshold_color='b'):
    try:
        if ax is None:
            import matplotlib.pylab
        import matplotlib.patches
        import matplotlib.collections
    except ImportError:
        raise ImportError('You must install the matplotlib library to plot the dendrogram. Use no_plot=True to calculate the dendrogram without plotting.')
    if ax is None:
        ax = matplotlib.pylab.gca()
        trigger_redraw = True
    else:
        trigger_redraw = False
    ivw = len(ivl) * 10
    dvw = mh + mh * 0.05
    ivticks = np.arange(5, len(ivl) * 10 + 5, 10)
    if orientation == 'top':
        ax.set_ylim([0, dvw])
        ax.set_xlim([0, ivw])
        xlines = icoords
        ylines = dcoords
        if no_labels:
            ax.set_xticks([])
            ax.set_xticklabels([])
        else:
            ax.set_xticks(ivticks)
            ax.set_xticklabels(ivl)
        ax.xaxis.set_ticks_position('bottom')
        lbls = ax.get_xticklabels()
        if leaf_rotation:
            map(lambda lbl: lbl.set_rotation(leaf_rotation), lbls)
        else:
            leaf_rot = float(_get_tick_rotation(len(ivl)))
            map(lambda lbl: lbl.set_rotation(leaf_rot), lbls)
        if leaf_font_size:
            map(lambda lbl: lbl.set_size(leaf_font_size), lbls)
        else:
            leaf_fs = float(_get_tick_text_size(len(ivl)))
            map(lambda lbl: lbl.set_rotation(leaf_fs), lbls)
        for line in ax.get_xticklines():
            line.set_visible(False)
    elif orientation == 'bottom':
        ax.set_ylim([dvw, 0])
        ax.set_xlim([0, ivw])
        xlines = icoords
        ylines = dcoords
        if no_labels:
            ax.set_xticks([])
            ax.set_xticklabels([])
        else:
            ax.set_xticks(ivticks)
            ax.set_xticklabels(ivl)
        lbls = ax.get_xticklabels()
        if leaf_rotation:
            map(lambda lbl: lbl.set_rotation(leaf_rotation), lbls)
        else:
            leaf_rot = float(_get_tick_rotation(p))
            map(lambda lbl: lbl.set_rotation(leaf_rot), lbls)
        if leaf_font_size:
            map(lambda lbl: lbl.set_size(leaf_font_size), lbls)
        else:
            leaf_fs = float(_get_tick_text_size(p))
            map(lambda lbl: lbl.set_rotation(leaf_fs), lbls)
        ax.xaxis.set_ticks_position('top')
        for line in ax.get_xticklines():
            line.set_visible(False)
    elif orientation == 'left':
        ax.set_xlim([0, dvw])
        ax.set_ylim([0, ivw])
        xlines = dcoords
        ylines = icoords
        if no_labels:
            ax.set_yticks([])
            ax.set_yticklabels([])
        else:
            ax.set_yticks(ivticks)
            ax.set_yticklabels(ivl)
        lbls = ax.get_yticklabels()
        if leaf_rotation:
            map(lambda lbl: lbl.set_rotation(leaf_rotation), lbls)
        if leaf_font_size:
            map(lambda lbl: lbl.set_size(leaf_font_size), lbls)
        ax.yaxis.set_ticks_position('left')
        for line in ax.get_yticklines():
            line.set_visible(False)
    elif orientation == 'right':
        ax.set_xlim([dvw, 0])
        ax.set_ylim([0, ivw])
        xlines = dcoords
        ylines = icoords
        if no_labels:
            ax.set_yticks([])
            ax.set_yticklabels([])
        else:
            ax.set_yticks(ivticks)
            ax.set_yticklabels(ivl)
        lbls = ax.get_yticklabels()
        if leaf_rotation:
            map(lambda lbl: lbl.set_rotation(leaf_rotation), lbls)
        if leaf_font_size:
            map(lambda lbl: lbl.set_size(leaf_font_size), lbls)
        ax.yaxis.set_ticks_position('right')
        for line in ax.get_yticklines():
            line.set_visible(False)
    colors_used = _remove_dups(color_list)
    color_to_lines = {}
    for color in colors_used:
        color_to_lines[color] = []
    for xline, yline, color in zip(xlines, ylines, color_list):
        color_to_lines[color].append(list(zip(xline, yline)))
    colors_to_collections = {}
    for color in colors_used:
        coll = matplotlib.collections.LineCollection(color_to_lines[color], colors=(color,))
        colors_to_collections[color] = coll
    for color in colors_used:
        if color != above_threshold_color:
            ax.add_collection(colors_to_collections[color])
    if above_threshold_color in colors_to_collections:
        ax.add_collection(colors_to_collections[above_threshold_color])
    if contraction_marks is not None:
        if orientation in ('left', 'right'):
            for x, y in contraction_marks:
                e = matplotlib.patches.Ellipse((y, x), width=dvw / 100, height=1.0)
                ax.add_artist(e)
                e.set_clip_box(ax.bbox)
                e.set_alpha(0.5)
                e.set_facecolor('k')
        if orientation in ('top', 'bottom'):
            for x, y in contraction_marks:
                e = matplotlib.patches.Ellipse((x, y), width=1.0, height=dvw / 100)
                ax.add_artist(e)
                e.set_clip_box(ax.bbox)
                e.set_alpha(0.5)
                e.set_facecolor('k')
    if trigger_redraw:
        matplotlib.pylab.draw_if_interactive()

def _append_singleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels):
    if lvs is not None:
        lvs.append(int(i))
    if ivl is not None:
        if leaf_label_func:
            ivl.append(leaf_label_func(int(i)))
        elif labels is not None:
            ivl.append(labels[int(i - n)])
        else:
            ivl.append(str(int(i)))

def _append_nonsingleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels, show_leaf_counts):
    if lvs is not None:
        lvs.append(int(i))
    if ivl is not None:
        if leaf_label_func:
            ivl.append(leaf_label_func(int(i)))
        elif show_leaf_counts:
            ivl.append('(' + str(int(Z[i - n, 3])) + ')')
        else:
            ivl.append('')

def _append_contraction_marks(Z, iv, i, n, contraction_marks):
    _append_contraction_marks_sub(Z, iv, int(Z[i - n, 0]), n, contraction_marks)
    _append_contraction_marks_sub(Z, iv, int(Z[i - n, 1]), n, contraction_marks)

def _append_contraction_marks_sub(Z, iv, i, n, contraction_marks):
    if i >= n:
        contraction_marks.append((iv, Z[i - n, 2]))
        _append_contraction_marks_sub(Z, iv, int(Z[i - n, 0]), n, contraction_marks)
        _append_contraction_marks_sub(Z, iv, int(Z[i - n, 1]), n, contraction_marks)

def _dendrogram_calculate_info(Z, p, truncate_mode, color_threshold=np.inf, get_leaves=True, orientation='top', labels=None, count_sort=False, distance_sort=False, show_leaf_counts=False, i=-1, iv=0.0, ivl=[], n=0, icoord_list=[], dcoord_list=[], lvs=None, mhr=False, current_color=[], color_list=[], currently_below_threshold=[], leaf_label_func=None, level=0, contraction_marks=None, link_color_func=None, above_threshold_color='b'):
    """
    Calculates the endpoints of the links as well as the labels for the
    the dendrogram rooted at the node with index i. iv is the independent
    variable value to plot the left-most leaf node below the root node i
    (if orientation='top', this would be the left-most x value where the
    plotting of this root node i and its descendents should begin).

    ivl is a list to store the labels of the leaf nodes. The leaf_label_func
    is called whenever ivl != None, labels == None, and
    leaf_label_func != None. When ivl != None and labels != None, the
    labels list is used only for labeling the leaf nodes. When
    ivl == None, no labels are generated for leaf nodes.

    When get_leaves==True, a list of leaves is built as they are visited
    in the dendrogram.

    Returns a tuple with l being the independent variable coordinate that
    corresponds to the midpoint of cluster to the left of cluster i if
    i is non-singleton, otherwise the independent coordinate of the leaf
    node if i is a leaf node.

    Returns
    -------
    A tuple (left, w, h, md), where:

      * left is the independent variable coordinate of the center of the
        the U of the subtree

      * w is the amount of space used for the subtree (in independent
        variable units)

      * h is the height of the subtree in dependent variable units

      * md is the max(Z[*,2]) for all nodes * below and including
        the target node.

    """
    if n == 0:
        raise ValueError('Invalid singleton cluster count n.')
    if i == -1:
        raise ValueError('Invalid root cluster index i.')
    if truncate_mode == 'lastp':
        if i < 2 * n - p and i >= n:
            d = Z[i - n, 2]
            _append_nonsingleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels, show_leaf_counts)
            if contraction_marks is not None:
                _append_contraction_marks(Z, iv + 5.0, i, n, contraction_marks)
            return (iv + 5.0, 10.0, 0.0, d)
        elif i < n:
            _append_singleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels)
            return (iv + 5.0, 10.0, 0.0, 0.0)
    elif truncate_mode in ('mtica', 'level'):
        if i > n and level > p:
            d = Z[i - n, 2]
            _append_nonsingleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels, show_leaf_counts)
            if contraction_marks is not None:
                _append_contraction_marks(Z, iv + 5.0, i, n, contraction_marks)
            return (iv + 5.0, 10.0, 0.0, d)
        elif i < n:
            _append_singleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels)
            return (iv + 5.0, 10.0, 0.0, 0.0)
    elif truncate_mode in ('mlab',):
        pass
    if i < n:
        _append_singleton_leaf_node(Z, p, n, level, lvs, ivl, leaf_label_func, i, labels)
        return (iv + 5.0, 10.0, 0.0, 0.0)
    aa = int(Z[i - n, 0])
    ab = int(Z[i - n, 1])
    if aa > n:
        na = Z[aa - n, 3]
        da = Z[aa - n, 2]
    else:
        na = 1
        da = 0.0
    if ab > n:
        nb = Z[ab - n, 3]
        db = Z[ab - n, 2]
    else:
        nb = 1
        db = 0.0
    if count_sort == 'ascending' or count_sort == True:
        if na > nb:
            ua = ab
            ub = aa
        else:
            ua = aa
            ub = ab
    elif count_sort == 'descending':
        if na > nb:
            ua = aa
            ub = ab
        else:
            ua = ab
            ub = aa
    elif distance_sort == 'ascending' or distance_sort == True:
        if da > db:
            ua = ab
            ub = aa
        else:
            ua = aa
            ub = ab
    elif distance_sort == 'descending':
        if da > db:
            ua = aa
            ub = ab
        else:
            ua = ab
            ub = aa
    else:
        ua = aa
        ub = ab
    uiva, uwa, uah, uamd = _dendrogram_calculate_info(Z=Z, p=p, truncate_mode=truncate_mode, color_threshold=color_threshold, get_leaves=get_leaves, orientation=orientation, labels=labels, count_sort=count_sort, distance_sort=distance_sort, show_leaf_counts=show_leaf_counts, i=ua, iv=iv, ivl=ivl, n=n, icoord_list=icoord_list, dcoord_list=dcoord_list, lvs=lvs, current_color=current_color, color_list=color_list, currently_below_threshold=currently_below_threshold, leaf_label_func=leaf_label_func, level=level + 1, contraction_marks=contraction_marks, link_color_func=link_color_func, above_threshold_color=above_threshold_color)
    h = Z[i - n, 2]
    if h >= color_threshold or color_threshold <= 0:
        c = above_threshold_color
        if currently_below_threshold[0]:
            current_color[0] = (current_color[0] + 1) % len(_link_line_colors)
        currently_below_threshold[0] = False
    else:
        currently_below_threshold[0] = True
        c = _link_line_colors[current_color[0]]
    uivb, uwb, ubh, ubmd = _dendrogram_calculate_info(Z=Z, p=p, truncate_mode=truncate_mode, color_threshold=color_threshold, get_leaves=get_leaves, orientation=orientation, labels=labels, count_sort=count_sort, distance_sort=distance_sort, show_leaf_counts=show_leaf_counts, i=ub, iv=iv + uwa, ivl=ivl, n=n, icoord_list=icoord_list, dcoord_list=dcoord_list, lvs=lvs, current_color=current_color, color_list=color_list, currently_below_threshold=currently_below_threshold, leaf_label_func=leaf_label_func, level=level + 1, contraction_marks=contraction_marks, link_color_func=link_color_func, above_threshold_color=above_threshold_color)
    max_dist = max(uamd, ubmd, h)
    icoord_list.append([uiva, uiva, uivb, uivb])
    dcoord_list.append([uah, h, h, ubh])
    if link_color_func is not None:
        v = link_color_func(int(i))
        if not isinstance(v, string_types):
            raise TypeError('link_color_func must return a matplotlib color string!')
        color_list.append(v)
    else:
        color_list.append(c)
    return ((uiva + uivb) / 2, uwa + uwb, h, max_dist)

def _leader_identify(tr, T):
    if tr.is_leaf():
        return T[tr.id]
    else:
        left = tr.get_left()
        right = tr.get_right()
        lfid = _leader_identify(left, T)
        rfid = _leader_identify(right, T)
        print('ndid: %d lid: %d lfid: %d rid: %d rfid: %d' % (tr.get_id(), left.get_id(), lfid, right.get_id(), rfid))
        if lfid != rfid:
            if lfid != -1:
                print('leader: %d with tag %d' % (left.id, lfid))
            if rfid != -1:
                print('leader: %d with tag %d' % (right.id, rfid))
            return -1
        else:
            return lfid

def _leaders_test_recurs_mark(tr, T):
    if tr.is_leaf():
        tr.asgn = T[tr.id]
    else:
        tr.asgn = -1
        _leaders_test_recurs_mark(tr.left, T)
        _leaders_test_recurs_mark(tr.right, T)
